"""Low level user interaction functions for image tools"""

import squishtest
from interops.libraries.squish_actions import common
from interops.libraries.xvi.interactions.objects.xvi_objects import Xvi_MainPage
from interops.libraries.miscellaneous.decorators import  LogMeta
from interops.libraries.xvi.interactions.common_objects_ops import get_text
import time

# Move to common lib later
def move_scrollbar_thumb(scrollbar, horizontal: bool, to: float, tolerance: float = 0.001):
    '''
    Move the Scrollbar thumb to the relative location within range [0, 100] by clicking inc/dec arrow
    '''
    if not scrollbar:
        return False
    range_ = scrollbar.maximum - scrollbar.minimum
    scale_factor =  range_ / 100
    if scrollbar and scrollbar.position < to * scale_factor and (to * scale_factor - scrollbar.position ) / range_ > tolerance:
        inc = True
    else:
        inc = False
    if inc:
        x = scrollbar.width - scrollbar.height // 2 if horizontal else scrollbar.width // 2
        y = scrollbar.height // 2 if horizontal else scrollbar.height - scrollbar.width // 2
    else:
        x = scrollbar.height // 2 if horizontal else scrollbar.width // 2
        y = scrollbar.height // 2 if horizontal else scrollbar.width // 2
    timeout = 10 #seconds
    start_time = time.time()
    while (not inc and scrollbar.position > to * scale_factor or (scrollbar.position - to * scale_factor) / range_ > tolerance) or (inc and scrollbar.position  < to * scale_factor or (to * scale_factor - scrollbar.position) / range_ > tolerance):
        squishtest.mousePress(scrollbar, x, y, squishtest.MouseButton.LeftButton)
        squishtest.mouseRelease()
        squishtest.snooze(.02)
        if time.time() - start_time > timeout:
            raise Exception("Something wrong with the control")
    return True

class ImageTools(metaclass = LogMeta):
    '''
    Class of Image Tools and their operations
    '''
    _buttons = {
        "Flip Horizontal" : [Xvi_MainPage.flip_Horizontal_Pane, Xvi_MainPage.flip_Horizontal_Pane_2],
        "Flip Vertical": [Xvi_MainPage.flip_Vertical_Pane, Xvi_MainPage.flip_Vertical_Pane_2],
        "Invert Black/White": [Xvi_MainPage.invert_BlackWhite_Pane, Xvi_MainPage.invert_BlackWhite_Pane_2],
        "Enhance via Display Equalization": [Xvi_MainPage.enhance_via_Display_Equalization_Pane, Xvi_MainPage.enhance_via_Display_Equalization_Pane_2],
        "Zoom Out" : [Xvi_MainPage.zoom_Out_Pane, Xvi_MainPage.zoom_Out_Pane_2],
        "Zoom In" : [Xvi_MainPage.zoom_In_Pane, Xvi_MainPage.zoom_In_Pane_2],
        "Set Scale" : [Xvi_MainPage.set_Scale_Pane, Xvi_MainPage.set_Scale_Pane_2],
        "Set Center" : [Xvi_MainPage.set_Center_Pane, Xvi_MainPage.set_Center_Pane_2],
        "Annotation" : [Xvi_MainPage.annotation_Pane, Xvi_MainPage.annotation_Pane_2],
        "Template Match" : [Xvi_MainPage.template_Match_Pane, Xvi_MainPage.template_Match_Pane_2],
        "Measure" : [Xvi_MainPage.measure_Pane, Xvi_MainPage.measure_Pane_2],
        "Show Center and 1 cm Graticule" : [Xvi_MainPage.show_Center_and_1_cm_Graticule_Pane, Xvi_MainPage.show_Center_and_1_cm_Graticule_Pane_2],
        "Show Field Edge Annotations" : [Xvi_MainPage.show_Field_Edge_Annotations_Pane, Xvi_MainPage.show_Field_Edge_Annotations_Pane_2],
        "Show Anatomy Annotation" : [Xvi_MainPage.show_Anatomy_Annotation_Pane, Xvi_MainPage.show_Anatomy_Annotation_Pane_2],
        "Show Miscellaneous Annotation" : [Xvi_MainPage.show_Misc_Annotation_Pane, Xvi_MainPage.show_Misc_Annotation_Pane_2],
        "Save Appearance" : [Xvi_MainPage.save_Appearance_Pane, Xvi_MainPage.save_Appearance_Pane_2],
        "Recall Appearance" : [Xvi_MainPage.recall_Appearance_Pane, Xvi_MainPage.recall_Appearance_Pane_2],
        "Print": [Xvi_MainPage.print_Pane, Xvi_MainPage.print_Pane_2],
        "Tile" : [Xvi_MainPage.tile_Pane, Xvi_MainPage.tile_Pane_2],
        "First Frame" : [Xvi_MainPage.first_Frame_Pane, Xvi_MainPage.first_Frame_Pane_2],
        "Previous Frame" : [Xvi_MainPage.previous_Frame_Pane, Xvi_MainPage.previous_Frame_Pane_2],
        "Play Movie" : [Xvi_MainPage.play_Movie_Pane, Xvi_MainPage.play_Movie_Pane_2],
        "Next Frame" : [Xvi_MainPage.next_Frame_Pane, Xvi_MainPage.next_Frame_Pane_2],
        "Last Frame" : [Xvi_MainPage.last_Frame_Pane, Xvi_MainPage.last_Frame_Pane_2],
        "Frame Location": [Xvi_MainPage.frame_Location_Pane, Xvi_MainPage.frame_Location_Pane_2]
    }

    def __init__(self, leftside: bool):
        squishtest.waitForObjectExists(Xvi_MainPage.edit_Image_Pane)
        self._leftside = leftside

    @property
    def image_loaded(self):
        try:
            label = squishtest.waitForObject(Xvi_MainPage.brightness_Label if self._leftside else Xvi_MainPage.brightness_Label_2)
            return label.enabled
        except LookupError:
            return False

    @property
    def brightness(self):
        self._brightness = get_text(Xvi_MainPage.brightness_Label if self._leftside else Xvi_MainPage.brightness_Label_2).replace('%', '')
        return self._brightness

    @brightness.setter
    def brightness(self, value):
        if self.image_loaded:
            brightness_scrollbar = squishtest.waitForObject(Xvi_MainPage.brightness_ScrollBar if self._leftside else Xvi_MainPage.brightness_ScrollBar_2)
            move_scrollbar_thumb(brightness_scrollbar, True, value)
            self._brightness = value
        else:
            raise LookupError("Brightness scrollbar is not enabled")

    @property
    def contrast(self):
        self._contrast = get_text(Xvi_MainPage.contrast_Label if self._leftside else Xvi_MainPage.contrast_Label_2).replace('%', '')
        return self._contrast

    @contrast.setter
    def contrast(self, value):
        if self.image_loaded:
            contrast_scrollbar = squishtest.waitForObject(Xvi_MainPage.contrast_ScrollBar if self._leftside else Xvi_MainPage.contrast_ScrollBar_2)
            move_scrollbar_thumb(contrast_scrollbar, True, value)
            self._contrast = value
        else:
            raise LookupError("Constrast scrollbar is not enabled")
    @property
    def zoom(self):
        self._zoom = int(get_text(Xvi_MainPage.zoom_Label if self._leftside else Xvi_MainPage.zoom_Label_2).replace("%", ""))
        return self._zoom

    @zoom.setter
    def zoom(self, value):
        zoom_level = [25, 50, 75, 100, 150, 200, 300, 400]
        closest = value
        if closest not in zoom_level:
            closest = min(zoom_level, key=lambda x: abs(x-value))
        while True:
            zm = int(get_text(Xvi_MainPage.zoom_Label if self._leftside else Xvi_MainPage.zoom_Label_2).replace("%", ""))
            if zm < closest:
                common.left_click_object(Xvi_MainPage.zoom_In_Pane if self._leftside else Xvi_MainPage.zoom_In_Pane_2)
            elif zm > closest:
                common.left_click_object(Xvi_MainPage.zoom_Out_Pane if self._leftside else Xvi_MainPage.zoom_Out_Pane_2)
            else:
                break
        self._zoom = closest
        return closest

    def click_button(self, which):
        if which in self._buttons:
            common.left_click_object(self._buttons[which][0 if self._leftside else 1])
            return True
        return False
